css:
/* ================= 全局变量 ================= */
:root {
  --album-bg: #ffffff;
  --text-main: #1A1A1A;     

  /* 受面板控制的动态颜色 */
  --theme-color: #007BFE; /* 箭头、标题、文字的颜色 */
  --btn-bg: #F0F0F0;      /* 右上角按钮的底色 */
}

/* 🌙 夜间模式颜色覆盖 */
.album-widget.dark-mode {
  --album-bg: #191919;
  --text-main: #D1D1D1;
  /* 夜间模式下如果没有自定义底色，给一个默认的暗色 */
  --btn-bg: #333333;        
}

/* ================= 容器主体 ================= */
.album-widget {
  position: relative; /* 为颜色面板提供定位基准 */
  width: 400px;
  height: 400px;
  background-color: var(--album-bg);
  border-radius: 0px; 
  display: flex;
  flex-direction: column;
  box-sizing: border-box;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  overflow: hidden;
  transition: background-color 0.4s ease;
}

/* ================= 顶部导航栏 ================= */
.album-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 16px;
}

.header-left {
  display: flex;
  align-items: center;
  gap: 6px;
}

.back-arrow {
  width: 10px;
  height: 10px;
  /* 使用动态主题色 */
  border-top: 2px solid var(--theme-color);
  border-left: 2px solid var(--theme-color);
  transform: rotate(-45deg);
  margin-top: 2px;
}

.header-title {
  color: var(--theme-color); /* 使用动态主题色 */
  font-size: 18px;
  font-weight: 500;
}

.header-right {
  display: flex;
  align-items: center;
  gap: 8px; 
}

.btn-select {
  background-color: var(--btn-bg);
  color: var(--theme-color);
  font-size: 14px;
  font-weight: 500;
  padding: 5px 12px;
  border-radius: 22px; 
  transition: background-color 0.4s ease, color 0.4s ease;
}

/* ================= 灰色底框（焊死在原地，保持形状） ================= */
.btn-more {
  background-color: var(--btn-bg);
  color: var(--theme-color);
  font-size: 14px;
  font-weight: 1000;
  letter-spacing: 1px;

  /* 固定底框的大小，这样文字怎么跑，框都不会变形 */
  width: 30px; 
  height: 30px;
  border-radius: 50px; 

  /* 让内部元素默认居中 */
  display: flex;
  align-items: center;
  justify-content: center;

  transition: background-color 0.4s ease, color 0.4s ease;
}

/* ================= 三个点（自由移动区） ================= */
.btn-more span {
  position: relative;

  /* 【位置控制区】 
     top: 正数往下移，负数往上移
     left: 正数往右移，负数往左移 
  */
  top: -4px;  /* 预设上移使其居中，你可以微调 */
  left: 1px;  /* 左右微调 */
}

/* ================= 文案区域 ================= */
.album-text {
  color: var(--text-main);
  font-size: 14px;
  line-height: 1.5;

  /* 👇 修改：把上下的 padding 去掉，留左右即可，垂直空间交给 flex 控制 */
  padding: 0 16px; 
  flex: 1; 
  transition: color 0.4s ease;

  /* 👇 核心魔法：使用 Flex 列布局 */
  display: flex;
  flex-direction: column;
}

/* 在文字上方放一个隐形弹簧，占 40% 的剩余空间 */
.album-text::before {
  content: "";
  flex: 3;
}

/* 在文字下方放一个隐形弹簧，占 60% 的剩余空间 */
.album-text::after {
  content: "";
  flex: 7;
}

/* ================= 六宫格图片区 ================= */
.album-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr); 
  gap: 4px; 

  /* 👇 【控制距离的区域】：我把边距拆开了，你可以自由调整 */
  padding-top: 0px;      /* 调这个：控制图片和上面文案的距离。正数往下推 */
  padding-left: 16px;    /* 左边距 */
  padding-right: 16px;   /* 右边距 */

  /* 🚨 核心在这里 🚨 */
  padding-bottom: 40px;  /* 👈 改这个：控制图片最下面距离底部的距离！数值越大，底部留白越多，图片就会被往上抬 */
}

.grid-img {
  width: 100%;
  aspect-ratio: 1 / 1; 
  border-radius: 0px; 
  background-color: #f5f5f5;
  background-size: cover;
  background-position: center;
  background-repeat: no-repeat;
}

.pic1, .pic2 { cursor: pointer; }

.dark-mode .grid-img {
  filter: brightness(0.85);
  background-color: #333333;
}

/* ================= 占位符图片替换区 ================= */
.pic1 { background-image: url('{{img1}}'); }
.pic2 { background-image: url('{{img2}}'); }
.pic3 { background-image: url('{{img3}}'); }
.pic4 { background-image: url('{{img4}}'); }
.pic5 { background-image: url('{{img5}}'); }
.pic6 { background-image: url('{{img6}}'); }

/* ================= 选色面板层 ================= */
.custom-color-overlay {
  position: absolute; inset: 0; background: rgba(255, 255, 255, 0.85); backdrop-filter: blur(8px);
  display: flex; align-items: center; justify-content: center; z-index: 100; opacity: 0; pointer-events: none; transition: opacity 0.3s;
}
.custom-color-overlay.show { opacity: 1; pointer-events: auto; }
.color-panel-box { 
  width: 320px; padding: 16px; display: flex; flex-direction: column; 
  background: #fff; border-radius: 12px; box-shadow: 0 4px 15px rgba(0,0,0,0.1); 
}
.color-row { display: flex; align-items: center; justify-content: space-between; }
.panel-title { font-size: 11px; font-weight: bold; color: #666; width: 60px; }
.color-tools { display: flex; gap: 8px; align-items: center; }
.macaron-grid { display: flex; gap: 6px; }
.macaron-dot { width: 18px; height: 18px; border-radius: 10%; cursor: pointer; border: 1px solid rgba(0,0,0,0.1); }
.system-picker { width: 24px; height: 24px; padding: 0; border: none; cursor: pointer; background: transparent; }
.confirm-btn { 
  width: 100%; margin-top: 12px; padding: 8px; border: none; border-radius: 6px; 
  background: var(--theme-color); color: #fff; font-weight: bold; cursor: pointer; transition: background 0.3s;
}

/* 选色面板在夜间模式的适配 */
.album-widget.dark-mode .custom-color-overlay { background: rgba(40, 40, 40, 0.85); }
.album-widget.dark-mode .color-panel-box { background: #333; color: #fff; }
.album-widget.dark-mode .panel-title { color: #aaa; }

* { margin: 0; padding: 0; box-sizing: border-box; }

body {
  background: transparent;
  width: 100%; height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: -apple-system, 'SF Pro Text', 'Helvetica Neue', sans-serif;
}

.widget {
  display: flex;
  flex-direction: column;
  align-items: center;
  /* 关键：整体用 filter drop-shadow，不用 box-shadow，透明底无虚影 */
  filter: drop-shadow(0 6px 18px rgba(0,0,0,0.18)) drop-shadow(0 2px 6px rgba(0,0,0,0.10));
  background: transparent;
}

/* ── 菜单主体 ── */
.menu-bar {
  display: flex;
  align-items: center;
  background: #ffffff;
  border-radius: 10px;
  padding: 0 2px;
  height: 36px;        /* 纵向缩窄：44px → 36px */
  width: fit-content;
}

/* ── 分隔线 ── */
.sep {
  width: 0.5px;
  height: 26px;
  background: rgba(0,0,0,0.15);
  flex-shrink: 0;
}

/* ── 菜单项 ── */
.menu-item {
  display: flex;
  flex-direction: row;
  align-items: center;
  justify-content: center;
  gap: 4px;
  padding: 0 18px;     /* 横向变宽：12px → 20px */
  height: 100%;
  cursor: pointer;
  color: #1a1a1a;
  border-radius: 8px;
  transition: background 0.12s;
  white-space: nowrap;
}
.menu-item:active {
  background: rgba(0,0,0,0.06);
}

.menu-item span {
  font-size: 15px;
  font-weight: 400;
  letter-spacing: -0.2px;
}
.menu-item svg {
  width: 15px;
  height: 15px;
  flex-shrink: 0;
}

/* Delete 置灰 */
.menu-item.muted {
  color: #b0b0b0;
}

/* 箭头 */
.menu-item.chevron {
  padding: 0 10px;
  color: #3a3a3a;
}
.menu-item.chevron svg {
  width: 12px;
  height: 12px;
}

/* ── 小尾巴（与菜单同色，drop-shadow 统一投影）── */
.tail {
  width: 24px;
  height: 12px;
  background: #ffffff;
  clip-path: polygon(0 0, 100% 0, 50% 100%);
  margin-top: -1px;
}
